<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {speakerColor} from './speaker-color';
import Icon from '../../shared/Icon.vue';
const props=defineProps<{items:readonly {id:string;label:string;enterpriseId:string|null;segments:number;segmentIds?:readonly string[];source?:'FILE'}[];disabled:boolean;loading?:boolean}>();
const page=ref(0),pageSize=24,pages=computed(()=>Math.ceil(props.items.length/pageSize));
const visible=computed(()=>props.items.slice(page.value*pageSize,(page.value+1)*pageSize));
watch(pages,count=>{page.value=Math.min(page.value,Math.max(0,count-1));});
const emit=defineEmits<{edit:[id:string];merge:[];split:[];undo:[]}>();
</script>
<template><section class="card mt16" aria-label="当前说话人"><div class="card-h"><div class="card-t" style="font-size:14px">说话人<span v-if="!loading||items.length">（{{items.length}}）</span></div></div><div class="card-p" style="padding:12px"><div v-if="loading&&!items.length" class="speaker-entry flex mb12 small muted" role="status">正在读取说话人…</div><div v-for="item in visible" :key="item.id" class="speaker-entry flex mb12" style="gap:10px"><span class="spk-av" style="width:30px;height:30px;font-size:12px" :style="{background:speakerColor(item.segmentIds?.[0]??item.id)}">{{item.label.slice(0,1)}}</span><div class="speaker-description"><div class="b" style="font-size:13px">{{item.label}} <span v-if="!item.enterpriseId" class="tag gray" style="font-size:10px">{{item.source==='FILE'?'文件标签':/^说话人 \d+$/.test(item.label)?'匿名':'自定义名称'}}</span></div><div class="small muted">{{item.enterpriseId?'已关联企业人员':'未匹配部门'}} · {{item.segments}} 段发言</div><div class="small" style="color:var(--amber)">{{item.source==='FILE'?'来自原文件 · 身份待确认':'暂无声纹匹配信息'}}</div></div><button type="button" class="btn sm" :disabled="disabled" @click="emit('edit',item.id)">编辑</button></div><nav v-if="pages>1" class="flex wrap" aria-label="说话人分页"><button class="btn sm" :disabled="!page" @click="page--">上一页</button><span class="small">{{page+1}} / {{pages}}</span><button class="btn sm" :disabled="page+1>=pages" @click="page++">下一页</button></nav><div class="divider"></div><div class="flex wrap" style="gap:6px"><button type="button" class="btn sm" :disabled="disabled||items.length<2" :title="items.length<2?'至少需要两位说话人':undefined" @click="emit('merge')"><Icon name="merge" :size="13"/> 合并说话人</button><button type="button" class="btn sm" :disabled="disabled||!items.some(item=>item.segments>1)" :title="items.some(item=>item.segments>1)?undefined:'至少需要一位说话人有两段发言'" @click="emit('split')"><Icon name="split" :size="13"/> 拆分说话人</button><button type="button" class="btn sm" :disabled="disabled" @click="emit('undo')"><Icon name="undo" :size="13"/> 撤销</button></div><div class="small muted mt8" title="当前人工标签用于后续纪要生成；已有确认和纪要快照保留，需显式重新生成。">命名后更新当前转写，新生成的纪要将使用已确认身份</div></div></section></template>
<style scoped>.speaker-entry{min-block-size:60px}.speaker-description{flex:1;min-width:0;overflow-wrap:anywhere}</style>
